-- Rifts World Book 2: Atlantis - bio-wizard transmutation, reconstruction,
-- eyes and sensors (printed 107-111): 39 rows as 'cybernetics' gear, by
-- Nate's decision of 2026-09-26 (survey decision 5). See
-- apps/character-creator/docs/surveys/atlantis.md.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-atlantis-bio-wizard-augmentation.sql
--
-- WHY CYBERNETICS: they are priced implants and procedures bought one at a
-- time, as the catalog's cybernetics are, and the Powerlord's entry (printed
-- 49) tells its player to pick two.
--
-- READ FROM A SCAN by book-extract-worker. Printed 110's OCR lost the heading
-- of Dragon's Breath; it was read off a render.
--
-- ROWS AND NOT ROWS:
--   * the ordinary P.S. increase (to 40) and the P.P., P.E. and Spd increases
--     are one row: the book prints the per-point rate beside the latter only.
--   * a tiered price stores its lowest tier; cost_note holds the schedule.
--   * NOT HERE: the Random Mutation Table (printed 107-108, rolled, not
--     bought; summarized in each transmutation row) and the four
--     transmutation tortures (printed 109, inflicted on captives, no price).
--   * All slugs carry a bio-wizard- prefix: the catalog's own cybernetic eyes
--     and senses are different items.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('bio-wizard-attribute-transmutation', 'Attribute Transmutation (P.S., P.P., P.E., Spd)', 'rifts', 'cybernetics', NULL, 100000, '100,000 credits per attribute point, or a trade of services (often indentured servitude). The book prints the rate beside P.P., P.E. and Spd; the P.S. increase above it states none.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Raises a physical attribute: P.S. to a maximum of 40 (not supernatural), P.P. to 21, P.E. to 21, Spd to 44 (30 mph/48 km). Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.107-108'),
('bio-wizard-beauty-transmutation', 'Physical Beauty Transmutation', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits per additional P.B. point', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Raises P.B. to a maximum of 26. Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-supernatural-strength', 'Supernatural Strength Transmutation', 'rifts', 'cybernetics', NULL, 50000000, '50 million credits to convert existing P.S., then 250,000 credits per additional point', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Converts ordinary P.S. into supernatural strength, to a maximum of P.S. 50. Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-size-transmutation', 'Increased Size Transmutation', 'rifts', 'cybernetics', NULL, 1000000, '1 million credits for under 15%, 2 million for 25%, 6 million for 50%, 10 million for 75%, 20 million to double natural size', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Increases size, up to double natural size. Doubling adds 3D4 to Spd and 2D4x10 S.D.C. (M.D.C. if already a mega-damage being). Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-sdc-transmutation', 'Additional S.D.C. Transmutation', 'rifts', 'cybernetics', NULL, 2000, '2,000 credits per S.D.C. point, up to 300 points', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Adds S.D.C., independent of any size increase, up to 300 points. Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-mega-damage-transformation', 'Mega-Damage Transformation', 'rifts', 'cybernetics', NULL, 500000000, '500 million credits, or trade and/or servitude', NULL, 0, NULL, NULL, NULL, NULL, NULL, 75, 'Transforms the subject into a mega-damage being with a base of 75 M.D.C. Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-mdc-transmutation', 'Additional M.D.C. Transmutation', 'rifts', 'cybernetics', NULL, 100000, '100,000 credits per M.D.C. point, up to 200 points', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Adds M.D.C. to a being that is already mega-damage (not supernatural beings or dragons), up to 200 points. Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-altered-environmental-structure', 'Altered Environmental Structure', 'rifts', 'cybernetics', NULL, 50000000, '50 million credits. Replacing a damaged containment chamber or lost fluid is available only from the Splugorth or a High Lord, at an incredibly high price.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Lets the subject survive in an environment alien to its body (underwater, a deadly atmosphere, outer space). It must stay covered by or immersed in transmutation fluid, in a containment chamber or environmental armor; without it the subject is at half melee attacks, bonuses, skills and hit points (or M.D.C.) and dies within 4D4 hours. Magic transmutation: 72 hours immersed in green transmutation fluid; permanent. Each attribute or category is a separate transmutation; past the sixth, roll on the Random Mutation Table (printed 107-108) and there is a 1-50% chance of death. Removed early, the gain is only 1D6, the subject becomes a deformed monstrosity (P.B. 4), is impervious to further transmutation, and takes three mutations.', 'Rifts World Book 2: Atlantis p.108'),
('bio-wizard-organ-restoration', 'Transmutation Healing: Organ Restoration', 'rifts', 'cybernetics', NULL, 200000, '200,000 credits per minor organ or artery; 500,000 per eye, kidney or liver; 1 million per lung or heart', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Restores a damaged or lost organ: 72 hours immersed in transmutation fluid per organ, with a 1-65% chance of death if removed early.', 'Rifts World Book 2: Atlantis p.108-109'),
('bio-wizard-wound-healing', 'Transmutation Healing: Wounds and Bones', 'rifts', 'cybernetics', NULL, 200000, '200,000 to 2 million credits for the 72-hour treatment, sometimes more, priced by how desperate the patient or family is', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Heals wounds and broken bones and restores hit points and S.D.C. (or M.D.C.) to full within 72 hours, without scarring and with no risk of death. It does not remove parasites, symbiotes, curses or insanity, or restore damaged organs.', 'Rifts World Book 2: Atlantis p.109'),
('bio-wizard-extra-human-arms', 'Additional Human Hands and Arms', 'rifts', 'cybernetics', NULL, 4000000, '8 million credits for a pair, 4 million for one', 'As P.S.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra pair of human hands and arms. Bonuses: +1 attack per melee, +1 to strike and parry. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.109'),
('bio-wizard-extra-appendage', 'Additional Non-Human Appendage', 'rifts', 'cybernetics', NULL, 4000000, '7 million credits for a pair, 4 million for one', 'As P.S.; claws add 1D6', 0, 'Up to twice body length (typically 5 to 12 ft / 1.5 to 3.6 m)', NULL, NULL, NULL, NULL, NULL, 'Tentacles or lobster-like pincer arms: up to two pairs on a human-size being, three on a giant (only one pair of claws). Claws used as hands are -50% to skills, with 40% of normal touch. Bonuses: +1 attack, +1 to strike and parry. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.109'),
('bio-wizard-wings', 'Wings and Flight', 'rifts', 'cybernetics', NULL, 20000000, '20 million credits', 'As P.S. (wing strikes as arms)', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Adds wings: flying speed 3D4x10, +1 to strike, parry and dodge while flying. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.109'),
('bio-wizard-chemical-spray', 'Chemical Spray (Bio-Wizard)', 'rifts', 'cybernetics', NULL, 5000000, '5 million credits or a trade of services', 'By chemical; burning vapors 1D6 S.D.C.', 0, '20 feet (6 m); the mist covers 10 feet (3 m) and dissipates in one melee', NULL, NULL, NULL, NULL, NULL, 'Glands in the arms, neck, mouth, chest or legs spray a mist or a targeted squirt, up to 10 times a day, as one extra melee attack at +2 to strike; victims save vs non-lethal toxin (16 or higher). One chemical of five: blinding (blind for 3D4 melees, -5 to strike, -10 to parry and dodge); stench (-6 to strike, parry and dodge, one attack lost for 2D4 melees); burning vapors (1D6 S.D.C., initiative lost, -4 to strike, parry and dodge for 1D6 melees); sleep (asleep in 1D4 melees for 1D6 minutes); or scent (trackable for up to 2 miles/3.2 km). Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.109-110'),
('bio-wizard-claws', 'Claws or Nails', 'rifts', 'cybernetics', NULL, 45000, '45,000 credits per hand', '2D4', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Natural claws or nails grown onto the hand. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-crab-claws', 'Crab Claws', 'rifts', 'cybernetics', NULL, 50000, '50,000 credits per hand', '2D6', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'A hand replaced by a pincer: -50% to skills using that hand, with 40% of normal touch. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-dragons-breath', 'Dragon''s Breath (Bio-Wizard)', 'rifts', 'cybernetics', NULL, 5000000, '5 million credits or a trade of services', '4D6', 0, '30 feet (9 m)', NULL, NULL, NULL, NULL, NULL, 'Lungs, throat and mouth modified to breathe a blast of magic fire, once per melee, as one attack. The heading is lost from the OCR and was read off a render of printed 110. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-plate-armor', 'Natural M.D.C. Plate Armor', 'rifts', 'cybernetics', NULL, 4000000, 'Light, 200 M.D.C.: 4 million credits; moderate, 350 M.D.C.: 8 million (-10% prowl); heavy, 500 M.D.C.: 12 million (-20% prowl and climb)', NULL, 0, NULL, NULL, NULL, NULL, NULL, 200, 'Natural armor plating like a rhinoceros or lobster, in three weights; mdc is the light plate. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-finger-claws', 'Retractable Finger Claws', 'rifts', 'cybernetics', NULL, 25000, '25,000 credits per finger', '1D4 per finger, plus P.S. bonus', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Two to three inch double-edged blades that retract into the fingers. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-knuckle-blades', 'Retractable Knuckle Blades', 'rifts', 'cybernetics', NULL, 150000, '150,000 credits', '3D6 plus P.S. bonus', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Four five-inch blades that extend from housings in the knuckles. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-forearm-blades', 'Retractable Forearm Blades', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits', '4D6 plus P.S. bonus', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Two or three blades, two feet (0.6 m) long, concealed in the forearm and used like a short sword. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-mini-tentacles', 'Retractable Mini-Tentacles', 'rifts', 'cybernetics', NULL, 7000000, '7 million credits or a trade of services', '1 point each', 0, '20 feet (6.1 m)', NULL, NULL, NULL, NULL, NULL, 'Eight tiny tentacles implanted anywhere on the upper torso. Bonuses: +1 attack, +1 to roll with impact, +1 to strike to entangle, +1 parry, pin or incapacitate on an unmodified 18-20, +15% climb, +5% acrobatics. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-spider-legs', 'Spider Legs (8)', 'rifts', 'cybernetics', NULL, 4000000, '4 million credits or a trade of services', 'As a punch', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'The lower torso replaced by an insect-like body on eight legs: running speed 40+4D6, leaps 20 ft (6 m) high or long, climbs most surfaces except glass or polished metal. Bonuses: +1 dodge, +5% prowl. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-elbow-spike', 'Spike: Elbow', 'rifts', 'cybernetics', NULL, 25000, '25,000 credits', '1D6', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'A bony spike on the elbow. Bonus: +1 parry. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-knee-spikes', 'Spikes: Knee', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits', '+1D6 to knee kicks', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Bony spikes on the knees. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-knuckle-spikes', 'Spikes: Knuckle', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits', '+1D6 to punches and backhands', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'Bony spikes on the knuckles. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-tail-spike', 'Spike: Tail', 'rifts', 'cybernetics', NULL, 6000000, '6 million credits', '2D6 plus P.S. bonus', 0, 'Hand to hand', NULL, NULL, NULL, NULL, NULL, 'A prehensile tail tipped with a bony spike that can grasp, climb and attack; only one tail may be added. It cannot perform hand skills (-70%) and can carry but not fire a gun. Bonuses: +1 attack, +10% climb, +5% balance. Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-stinger', 'Stinger', 'rifts', 'cybernetics', NULL, 5000000, '5 million credits or a trade of services', 'Poison 6D6 S.D.C. or 2D6 M.D.; convulsions 2D6', 0, 'Striking distance', NULL, NULL, NULL, NULL, NULL, 'A retractable needle in the tail, wrist or mouth, one extra attack at +1 to strike; victims save vs lethal toxin (14 or higher, no effect on a save). One chemical of three: poison (sick, one attack lost and -2 to all combat rolls for 6D6 minutes); convulsions (2D4 melees unable to act, defend, speak or concentrate, at half speed); or paralysis (collapses and cannot move for 1D4 minutes). Bio-wizard reconstruction: grown onto the body, heals like natural tissue and needs no power source; its damage is S.D.C. unless the recipient is already a mega-damage being.', 'Rifts World Book 2: Atlantis p.110'),
('bio-wizard-eye-of-eylor', 'Eye of Eylor (Bio-Wizard Eye)', 'rifts', 'cybernetics', NULL, 10000000, '10 million credits or a trade of services', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A living eye from the planet Eylor, replacing a natural eye or added as a third eye (usually forehead or chest): perfect 20/20 vision, nightvision 600 ft (183 m), telescopic vision to 6000 ft (1800 m) with 300x magnification, and, at no I.S.P. or P.P.E. cost, see aura, see the invisible, sense magic and see P.P.E. energy. Adds 20 P.P.E. to the base.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-human-eye', 'Human Eye (Bio-Wizard)', 'rifts', 'cybernetics', NULL, 75000, '75,000 credits per eye', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A natural human replacement eye in the color of choice, with perfect 20/20 vision.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-infrared-eye', 'Infrared Eye (Bio-Wizard)', 'rifts', 'cybernetics', NULL, 300000, '300,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A large-pupiled eye with a violet or alizarin iris that sees infrared and ultraviolet light, into the dark at about half normal day range, and through murky water; colors are shifted to blue, green and violet hues. It cannot see the invisible or heat emanations. 20/20 vision.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-nightvision-eye', 'Nightvision Eye (Bio-Wizard)', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A large dark eye: nightvision to 1000 ft (305 m) in total darkness, but day vision is halved and bright light hurts.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-polarized-eye', 'Polarized Eye (Bio-Wizard)', 'rifts', 'cybernetics', NULL, 100000, '100,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A natural-looking eye that filters glare automatically and can look straight at the sun; 20/20 vision. Bonus: +10% to sense of direction.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-amplified-hearing', 'Amplified Hearing (Bio-Wizard Ear)', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits', NULL, 0, 'Pinpoints sounds of 70 dB or more up to 600 feet (183 m)', NULL, NULL, NULL, NULL, NULL, 'A bat-like replacement ear: hears a whisper at 75 ft (22.9 m), quiet conversation at 150 ft (45.8 m) and normal conversation at 300 ft (90 m). Bonuses: +2 initiative, +1 to parry and dodge.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-heat-detection', 'Heat Detection (Bio-Wizard Sensor)', 'rifts', 'cybernetics', NULL, 2000000, '2 million credits or a trade of services', NULL, 0, '60 feet (18.3 m)', NULL, NULL, NULL, NULL, NULL, 'Antennae or long hairs on the head or shoulders that sense giant-size heat sources only. Bonus: +1 initiative.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-internal-clock', 'Internal Clock (Bio-Wizard Sensor)', 'rifts', 'cybernetics', NULL, 80000, '80,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Senses the approximate time of day and season.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-sense-of-direction', 'Instinctive Sense of Direction (Bio-Wizard Sensor)', 'rifts', 'cybernetics', NULL, 200000, '200,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An instinctive sense of direction equal to an 80% skill.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-molecular-analyzer', 'Molecular Analyzer (Bio-Wizard Sensor)', 'rifts', 'cybernetics', NULL, 8000000, '8 million credits or a trade of services', NULL, 0, '20 feet (6.1 m)', NULL, NULL, NULL, NULL, NULL, 'Built into the mouth or antennae: recognize a known scent or chemical 70%, track by smell 70%, recognize poison 88%, detect temperature changes 80%.', 'Rifts World Book 2: Atlantis p.111'),
('bio-wizard-motion-detection', 'Motion Detection (Bio-Wizard Sensor)', 'rifts', 'cybernetics', NULL, 4000000, '4 million credits or a trade of services', NULL, 0, '60 feet (18.3 m)', NULL, NULL, NULL, NULL, NULL, 'Antennae or long hairs that feel air movement. Bonuses: +1 initiative, and blindness penalties are halved.', 'Rifts World Book 2: Atlantis p.111');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'the 39 bio-wizard augmentation rows are in' AS assertion, count(*) AS got, 39 AS want
  FROM gear WHERE slug IN ('bio-wizard-attribute-transmutation', 'bio-wizard-beauty-transmutation', 'bio-wizard-supernatural-strength', 'bio-wizard-size-transmutation', 'bio-wizard-sdc-transmutation', 'bio-wizard-mega-damage-transformation', 'bio-wizard-mdc-transmutation', 'bio-wizard-altered-environmental-structure', 'bio-wizard-organ-restoration', 'bio-wizard-wound-healing', 'bio-wizard-extra-human-arms', 'bio-wizard-extra-appendage', 'bio-wizard-wings', 'bio-wizard-chemical-spray', 'bio-wizard-claws', 'bio-wizard-crab-claws', 'bio-wizard-dragons-breath', 'bio-wizard-plate-armor', 'bio-wizard-finger-claws', 'bio-wizard-knuckle-blades', 'bio-wizard-forearm-blades', 'bio-wizard-mini-tentacles', 'bio-wizard-spider-legs', 'bio-wizard-elbow-spike', 'bio-wizard-knee-spikes', 'bio-wizard-knuckle-spikes', 'bio-wizard-tail-spike', 'bio-wizard-stinger', 'bio-wizard-eye-of-eylor', 'bio-wizard-human-eye', 'bio-wizard-infrared-eye', 'bio-wizard-nightvision-eye', 'bio-wizard-polarized-eye', 'bio-wizard-amplified-hearing', 'bio-wizard-heat-detection', 'bio-wizard-internal-clock', 'bio-wizard-sense-of-direction', 'bio-wizard-molecular-analyzer', 'bio-wizard-motion-detection') AND category = 'cybernetics' AND source_book LIKE 'Rifts World Book 2: Atlantis p.%';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-atlantis-bio-wizard-augmentation.sql');
